for (const pack of packs) {
  for (const message of Object.values(pack.messages)) if (typeof message === 'object') Object.freeze(message);
  Object.freeze(pack.messages);
  if (pack.locale.aliases) Object.freeze(pack.locale.aliases);
  Object.freeze(pack.locale); Object.freeze(pack);
}
export default Object.freeze(packs);
